{"version":3,"file":"app.jsdbx","sources":["../../src/client/app.tsx","../../src/client/app.css"],"sourcesContent":["import React from 'react';
import NavHeader from './components/shared/NavHeader';
import './app.css';

/* ─── Donut Chart SVG Helper ─── */
function DonutChart() {
  const data = [
    { label: 'P1 Critical', value: 148, color: '#ef4444' },
    { label: 'P2 High', value: 386, color: '#f59e0b' },
    { label: 'P3 Medium', value: 562, color: '#3b82f6' },
    { label: 'P4 Low', value: 246, color: '#64748b' },
  ];
  const total = data.reduce((s, d) => s + d.value, 0);
  const cx = 90, cy = 90, r = 70, inner = 45;
  let cumulative = 0;

  function getArc(startAngle: number, endAngle: number, outerR: number, innerR: number) {
    const startOuter = polarToCartesian(cx, cy, outerR, startAngle);
    const endOuter = polarToCartesian(cx, cy, outerR, endAngle);
    const startInner = polarToCartesian(cx, cy, innerR, endAngle);
    const endInner = polarToCartesian(cx, cy, innerR, startAngle);
    const largeArc = endAngle - startAngle > 180 ? 1 : 0;
    return [
      `M ${startOuter.x} ${startOuter.y}`,
      `A ${outerR} ${outerR} 0 ${largeArc} 1 ${endOuter.x} ${endOuter.y}`,
      `L ${startInner.x} ${startInner.y}`,
      `A ${innerR} ${innerR} 0 ${largeArc} 0 ${endInner.x} ${endInner.y}`,
      'Z'
    ].join(' ');
  }

  function polarToCartesian(cx: number, cy: number, radius: number, angleDeg: number) {
    const rad = ((angleDeg - 90) * Math.PI) / 180;
    return { x: cx + radius * Math.cos(rad), y: cy + radius * Math.sin(rad) };
  }

  return (
    <div className="donut-wrapper">
      <svg width="180" height="180" viewBox="0 0 180 180">
        {data.map((seg, i) => {
          const startAngle = (cumulative / total) * 360;
          cumulative += seg.value;
          const endAngle = (cumulative / total) * 360;
          return <path key={i} d={getArc(startAngle, endAngle, r, inner)} fill={seg.color} />;
        })}
        <text x={cx} y={cy - 6} textAnchor="middle" fill="#e2e8f0" fontSize="20" fontWeight="700">1,342</text>
        <text x={cx} y={cy + 14} textAnchor="middle" fill="#94a3b8" fontSize="11">total</text>
      </svg>
      <div className="donut-legend">
        {data.map((seg, i) => (
          <div key={i} className="legend-item">
            <span className="legend-dot" style={{ background: seg.color }}></span>
            <span className="legend-label">{seg.label}</span>
            <span className="legend-value">{seg.value}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

