  { id: 'CMP-482959', desc: 'Wrong item substituted', store: 'Bengaluru Airport Road DS, Bengaluru', storeId: 'DS-1630', priority: 'P3', agent: 'K. Reddy', agentId: 'AG-1502', status: 'Escalated — L2', age: '2h 55m', ageClass: 'age-yellow' },
