  { id: 'CMP-483370', desc: 'Order delivered 46 min late', store: 'Hyderabad Outer Ring DS, Hyderabad', storeId: 'DS-1966', priority: 'P2', agent: 'Unassigned', agentId: '', status: 'Unassigned', age: '2h 47m', ageClass: 'age-yellow' },
  { id: 'CMP-483507', desc: 'Wrong item substituted', store: 'Delhi NCR Outer Ring DS, Delhi NCR', storeId: 'DS-1959', priority: 'P4', agent: 'A. Verma', agentId: 'AG-0917', status: 'In progress', age: '3h 56m', ageClass: 'age-red' },
  { id: 'CMP-483644', desc: 'Partial order cancelled at pack', store: 'Delhi NCR Industrial Belt DS, Delhi NCR', storeId: 'DS-2169', priority: 'P2', agent: 'R. Iyer', agentId: 'AG-2041', status: 'In progress', age: '0h 24m', ageClass: 'age-green' },
  { id: 'CMP-483781', desc: 'Order delivered 46 min late', store: 'Hyderabad IT Corridor DS, Hyderabad', storeId: 'DS-1861', priority: 'P3', agent: 'A. Verma', agentId: 'AG-0917', status: 'Awaiting customer', age: '2h 43m', ageClass: 'age-yellow' },
];

function getPriorityClass(p: string) {
  switch (p) {
    case 'P1': return 'priority-p1';
    case 'P2': return 'priority-p2';
    case 'P3': return 'priority-p3';
    case 'P4': return 'priority-p4';
    default: return '';
  }
}

/* ─── Main Dashboard Component ─── */
