","/* ═══════════════════════════════════════════════════════════════
   Operations Dashboard - DarkOps
   ═══════════════════════════════════════════════════════════════ */

:root {
  --cc-bg-primary: #0a0e1a;
  --cc-bg-card: #131a2e;
  --cc-border: #1e2a45;
  --cc-accent: #00c896;
  --cc-accent-glow: rgba(0, 200, 150, 0.1);
  --cc-warning: #f59e0b;
  --cc-critical: #ef4444;
  --cc-text-primary: #e2e8f0;
  --cc-text-secondary: #94a3b8;
  --cc-radius: 14px;
  --cc-spacing: 24px;
  --cc-blue: #3b82f6;
}

/* ─── Base ─── */
.ops-dashboard {
  background: var(--cc-bg-primary);
  min-height: 100vh;
  color: var(--cc-text-primary);
  font-family: -apple-system, BlinkMacSystemFont, 'Inter', 'Segoe UI', sans-serif;
  padding-bottom: 60px;
}

/* ─── Page Header ─── */
.ops-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  padding: 32px var(--cc-spacing) 12px;
  max-width: 1440px;
  margin: 0 auto;
}

.ops-title {
  font-size: 28px;
  font-weight: 700;
  margin: 0 0 6px;
  color: var(--cc-text-primary);
}

.ops-subtitle {
  font-size: 14px;
  color: var(--cc-text-secondary);
  margin: 0;
}

.ops-header-right {
  padding-top: 8px;
}

.ops-updated {
  font-size: 13px;
  color: var(--cc-text-secondary);
}

.live-dot {
  color: var(--cc-accent);
  font-size: 10px;
}

/* ─── KPI Cards Row ─── */
.kpi-row {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
  padding: 20px var(--cc-spacing);
  max-width: 1440px;
  margin: 0 auto;
}

.kpi-card {
  background: var(--cc-bg-card);
  border: 1px solid var(--cc-border);
  border-radius: var(--cc-radius);
  padding: 20px;
  display: flex;
  flex-direction: column;
  position: relative;
  overflow: hidden;
}

.kpi-card-accent {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
}

.accent-default {
  background: var(--cc-accent);
}

.accent-red {
  background: var(--cc-critical);
}

.kpi-label {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.5px;
  color: var(--cc-text-secondary);
  margin-bottom: 10px;
  text-transform: uppercase;
}

.kpi-value {
  font-size: 32px;
  font-weight: 700;
  color: var(--cc-text-primary);
  line-height: 1.1;
  margin-bottom: 8px;
}

.kpi-value-green {
  color: var(--cc-accent);
}

.kpi-sub {
  font-size: 12px;
  color: var(--cc-text-secondary);
  line-height: 1.4;
}

/* ─── Three Panel Row ─── */
.panels-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  padding: 12px var(--cc-spacing);
  max-width: 1440px;
  margin: 0 auto;
}

.panel-card {
  background: var(--cc-bg-card);
  border: 1px solid var(--cc-border);
  border-radius: var(--cc-radius);
  padding: 24px;
}

.panel-title {
  font-size: 16px;
  font-weight: 600;
  color: var(--cc-text-primary);
  margin: 0 0 6px;
}

.panel-subtitle {
  font-size: 12px;
  color: var(--cc-text-secondary);
  margin: 0 0 20px;
}

/* ─── Donut Chart ─── */
.donut-wrapper {
  display: flex;
  align-items: center;
  gap: 24px;
}

.donut-legend {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 8px;
}

.legend-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  flex-shrink: 0;
}

.legend-label {
  font-size: 12px;
  color: var(--cc-text-secondary);
  min-width: 80px;
}

.legend-value {
  font-size: 13px;
  font-weight: 600;
  color: var(--cc-text-primary);
}

/* ─── Horizontal Bar Chart ─── */
.hbar-chart {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.hbar-row {
  display: flex;
  align-items: center;
  gap: 12px;
}

.hbar-label {
  font-size: 12px;
  color: var(--cc-text-secondary);
  min-width: 120px;
  text-align: right;
}

.hbar-track {
  flex: 1;
  height: 22px;
  background: rgba(255, 255, 255, 0.04);
  border-radius: 4px;
  overflow: hidden;
}

.hbar-fill {
  height: 100%;
  border-radius: 4px;
  transition: width 0.4s ease;
}

.hbar-blue { background: var(--cc-blue); }
.hbar-green { background: var(--cc-accent); }
.hbar-teal { background: #14b8a6; }

.hbar-value {
  font-size: 12px;
  font-weight: 600;
  color: var(--cc-text-primary);
  min-width: 32px;
}

.hbar-axis {
  display: flex;
  justify-content: space-between;
  margin-left: 132px;
  margin-right: 44px;
  padding-top: 4px;
  border-top: 1px solid var(--cc-border);
}

.hbar-axis span {
  font-size: 10px;
  color: var(--cc-text-secondary);
}

/* ─── Vertical Bar Chart ─── */
.vbar-chart {
  display: flex;
  gap: 8px;
  height: 180px;
  margin-top: 8px;
}

.vbar-y-axis {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 0 8px 24px 0;
}

.vbar-y-axis span {
  font-size: 10px;
  color: var(--cc-text-secondary);
}

.vbar-bars {
  flex: 1;
  display: flex;
  gap: 12px;
  align-items: flex-end;
  border-left: 1px solid var(--cc-border);
  border-bottom: 1px solid var(--cc-border);
  padding: 0 12px 24px;
  position: relative;
}

.vbar-col {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  height: 100%;
}

.vbar-bar-wrapper {
  flex: 1;
  width: 100%;
  display: flex;
  align-items: flex-end;
  justify-content: center;
}

.vbar-bar {
  width: 28px;
  border-radius: 4px 4px 0 0;
  transition: height 0.4s ease;
}

.vbar-blue { background: var(--cc-blue); }
.vbar-yellow { background: var(--cc-warning); }

.vbar-label {
  font-size: 10px;
  color: var(--cc-text-secondary);
  margin-top: 8px;
  text-align: center;
  position: absolute;
  bottom: 4px;
}

.vbar-col:nth-child(1) .vbar-label { left: 8%; }
.vbar-col:nth-child(2) .vbar-label { left: 26%; }
.vbar-col:nth-child(3) .vbar-label { left: 44%; }
.vbar-col:nth-child(4) .vbar-label { left: 63%; }
.vbar-col:nth-child(5) .vbar-label { left: 79%; }

/* ─── Queue Section ─── */
.queue-section {
  background: var(--cc-bg-card);
  border: 1px solid var(--cc-border);
  border-radius: var(--cc-radius);
  margin: 12px var(--cc-spacing) 0;
  padding: 24px;
  max-width: 1440px;
  margin-left: auto;
  margin-right: auto;
}

.queue-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 16px;
}

.queue-badge {
  background: rgba(0, 200, 150, 0.12);
  color: var(--cc-accent);
  font-size: 12px;
  font-weight: 600;
  padding: 6px 14px;
  border-radius: 20px;
  border: 1px solid rgba(0, 200, 150, 0.25);
}

.queue-controls {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--cc-border);
}

.queue-tabs {
  display: flex;
  gap: 4px;
}

.tab-btn {
  background: transparent;
  border: 1px solid var(--cc-border);
  color: var(--cc-text-secondary);
  font-size: 12px;
  padding: 6px 14px;
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.2s;
}

.tab-btn:hover {
  border-color: var(--cc-accent);
  color: var(--cc-text-primary);
}

.tab-active {
  background: rgba(0, 200, 150, 0.1);
  border-color: var(--cc-accent);
  color: var(--cc-accent);
}

.queue-legend {
  font-size: 12px;
  color: var(--cc-text-secondary);
}

/* ─── Age Colors ─── */
.age-green { color: var(--cc-accent); font-weight: 600; }
.age-yellow { color: var(--cc-warning); font-weight: 600; }
.age-red { color: var(--cc-critical); font-weight: 600; }

/* ─── Queue Table ─── */
.queue-table-wrapper {
  overflow-x: auto;
}

.queue-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

.queue-table thead tr {
  border-bottom: 1px solid var(--cc-border);
}

.queue-table th {
  text-align: left;
  padding: 10px 12px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.4px;
  color: var(--cc-text-secondary);
  text-transform: uppercase;
  white-space: nowrap;
}

.queue-table td {
  padding: 12px 12px;
  border-bottom: 1px solid rgba(30, 42, 69, 0.5);
  vertical-align: middle;
}

.queue-table tbody tr:hover {
  background: rgba(255, 255, 255, 0.02);
}

.complaint-id {
  font-weight: 600;
  color: var(--cc-text-primary);
  font-size: 13px;
}

.complaint-desc {
  font-size: 11px;
  color: var(--cc-text-secondary);
  margin-top: 2px;
}

.store-name {
  font-size: 12px;
  color: var(--cc-text-primary);
}

.store-id {
  font-size: 11px;
  color: var(--cc-text-secondary);
  margin-top: 2px;
}

/* ─── Priority Badges ─── */
.priority-badge {
  display: inline-block;
  padding: 3px 10px;
  border-radius: 12px;
  font-size: 11px;
  font-weight: 700;
  color: #fff;
  text-align: center;
}

.priority-p1 { background: var(--cc-critical); }
.priority-p2 { background: var(--cc-warning); }
.priority-p3 { background: var(--cc-blue); }
.priority-p4 { background: #64748b; }

/* ─── Agent Unassigned ─── */
.agent-unassigned {
  color: var(--cc-critical);
  font-weight: 600;
}

.status-text {
  font-size: 12px;
  color: var(--cc-text-secondary);
}

/* ─── Responsive ─── */
@media (max-width: 1200px) {
  .kpi-row {
    grid-template-columns: repeat(3, 1fr);
  }
  .panels-row {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 768px) {
  .kpi-row {
    grid-template-columns: repeat(2, 1fr);
  }
  .ops-header {
    flex-direction: column;
    gap: 12px;
  }
  .queue-controls {
    flex-direction: column;
    align-items: flex-start;
    gap: 12px;
  }
}
